parsed.tgrl:
grl TeslaModelSAutopilot {
  actor Driver {
    goal MonitorRoadAndRemainResponsible;
    goal SetCruisingSpeedAndEnableAutopilot;
    goal KeepHandsOnWheelAndRespondToAlerts;
    softGoal UseAutopilotOnlyWhenAbleToSupervise;
  }
  actor TeslaModelSAutopilot {
    goal AssistWithLongitudinalAndLateralControl;
    goal DetectLaneMarkingsAndObjectsAhead;
    goal MaintainDriverSetSpeedAndAdaptToLeadVehicle;
    goal KeepVehicleCenteredInLane;
    goal ProvideForwardCollisionWarningAndAutomaticEmergencyBraking;
    softGoal SupportSafeOperationInIntendedConditions;
  }
  actor CarDriver {
    softGoal TravelSafelyAndInteractPredictablyWithTheModelS;
  }
  actor TruckDriver {
    goal CrossOrJoinTheRoadSafely;
    softGoal InteractPredictablyWithTheModelS;
  }
  actor Motorcyclist {
    softGoal TravelSafelyAndInteractPredictablyWithTheModelS;
  }
  actor Pedestrian {
    softGoal RemainSafeNearRoadTraffic;
  }
  actor OtherRoadUsers {
    softGoal TravelSafelyAroundTheModelS;
  }
}

